(function () {
    // Ambil semua elemen dengan attribute data-track
    const tracks = document.querySelectorAll("[data-track]");
    if (!tracks.length) return;
  
    tracks.forEach(track => {
      // Hindari double init
      if (track.dataset.initialized) return;
      track.dataset.initialized = "true";
  
      // Duplicate isi untuk looping
      track.innerHTML += track.innerHTML;
  
      let position = 0;
  
      // Ambil dari data attribute
      let baseSpeed = parseFloat(track.dataset.speed) || 1.5;
      let speed = baseSpeed;
      let targetSpeed = baseSpeed;
  
      // Direction: left (default) atau right
      const direction = track.dataset.direction === "right" ? 1 : -1;
  
      // Hover effect
      track.addEventListener("mouseenter", () => {
        targetSpeed = baseSpeed * 0.1;
      });
  
      track.addEventListener("mouseleave", () => {
        targetSpeed = baseSpeed;
      });
  
      function animate() {
        // Smooth speed transition
        speed += (targetSpeed - speed) * 0.05;
  
        // Update posisi sesuai arah
        position += speed * direction;
  
        const halfWidth = track.scrollWidth / 2;
  
        // Loop tanpa glitch
        if (direction === -1 && Math.abs(position) >= halfWidth) {
          position += halfWidth;
        } else if (direction === 1 && position >= 0) {
          position -= halfWidth;
        }
  
        track.style.transform = `translateX(${position}px)`;
  
        requestAnimationFrame(animate);
      }
  
      animate();
    });
  })();